// smoke.spec.js — tool-specific checks for the WAV to MP3 Converter.
// Fixture: tests/fixtures/sample.wav, a fictional 2 s piano-like arpeggio (44.1 kHz stereo, ~350 KB),
// generated by `node tests/make-fixtures.js`.
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');
const fflate = require('../vendor/fflate/fflate.js');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const WAV = fs.readFileSync(fixture('sample.wav'));

const isMp3 = (b) => (b[0] === 0x49 && b[1] === 0x44 && b[2] === 0x33) || (b[0] === 0xff && (b[1] & 0xe0) === 0xe0);

async function convert(page, { files = fixture('sample.wav'), kbps } = {}) {
  await page.setInputFiles('#file-input', files);
  if (kbps) await page.selectOption('#bitrate', String(kbps));
  await page.click('#convert');
  const count = Array.isArray(files) ? files.length : 1;
  await expect(page.locator('.conv-row[data-status="done"]')).toHaveCount(count, { timeout: 30_000 });
}

async function downloadFirst(page) {
  const [download] = await Promise.all([page.waitForEvent('download'), page.locator('.conv-row__download').first().click()]);
  return { download, bytes: fs.readFileSync(await download.path()) };
}

test.describe('WAV to MP3 Converter', () => {
  test('dropping sample.wav produces a downloadable MP3 smaller than the WAV', async ({ page }) => {
    const errors = [];
    page.on('pageerror', (e) => errors.push(String(e)));
    await page.goto('./');
    await expect(page.locator('#empty-state')).toContainText('never leaves your device');
    await convert(page);
    const link = page.locator('.conv-row__download');
    await expect(link).toHaveText('Download sample.mp3');
    const { download, bytes } = await downloadFirst(page);
    expect(download.suggestedFilename()).toBe('sample.mp3');
    expect(isMp3(bytes)).toBeTruthy();
    expect(bytes.length).toBeGreaterThan(10_000); // ~2 s at 192 kbps is about 48 KB
    expect(bytes.length).toBeLessThan(WAV.length);
    expect(errors).toEqual([]);
  });

  test('result row shows original size, MP3 size, reduction percentage and duration', async ({ page }) => {
    await page.goto('./');
    await convert(page);
    const row = page.locator('.conv-row').first();
    await expect(row.locator('.conv-orig')).toHaveText('Original 345 KB');
    await expect(row.locator('.conv-new')).toHaveText(/^MP3 \d+(\.\d)? KB$/);
    await expect(row.locator('.conv-saving')).toHaveText(/^Saving \d{1,2}\.\d% smaller$/);
    await expect(row.locator('.conv-duration')).toHaveText('Length 0:02');
    const { bytes } = await downloadFirst(page);
    const pct = Number((await row.locator('.conv-saving').textContent()).match(/[\d.]+/)[0]);
    const exact = (1 - bytes.length / WAV.length) * 100;
    expect(pct).toBeLessThanOrEqual(exact);
    expect(exact - pct).toBeLessThan(0.1);
  });

  test('320 kbps gives a larger file than 128 kbps for the same input', async ({ page }) => {
    await page.goto('./');
    await convert(page, { kbps: 128 });
    const small = (await downloadFirst(page)).bytes.length;
    // Changing the bitrate re-enables Convert and re-encodes the same file.
    await page.selectOption('#bitrate', '320');
    await expect(page.locator('#convert')).toBeEnabled();
    await page.click('#convert');
    await expect(page.locator('.conv-format')).toContainText('320 kbps', { timeout: 30_000 });
    const big = (await downloadFirst(page)).bytes.length;
    expect(big).toBeGreaterThan(small * 2);
  });

  test('three files and Download all produce a ZIP with three MP3 files', async ({ page }) => {
    await page.goto('./');
    const files = [
      { name: 'sample.wav', mimeType: 'audio/wav', buffer: WAV },
      { name: 'sample.wav', mimeType: 'audio/wav', buffer: WAV },
      { name: 'Café melody ♪.wav', mimeType: 'audio/wav', buffer: WAV },
    ];
    await convert(page, { files });
    const zipBtn = page.locator('#download-zip');
    await expect(zipBtn).toBeVisible();
    const [download] = await Promise.all([page.waitForEvent('download'), zipBtn.click()]);
    expect(download.suggestedFilename()).toBe('mp3-files.zip');
    const entries = fflate.unzipSync(new Uint8Array(fs.readFileSync(await download.path())));
    const names = Object.keys(entries).sort();
    expect(names).toEqual(['Café melody ♪.mp3', 'sample-2.mp3', 'sample.mp3']);
    for (const n of names) {
      expect(isMp3(entries[n])).toBeTruthy();
      expect(entries[n].length).toBeLessThan(WAV.length);
    }
  });

  test('a non audio file is rejected with a message, valid files still go through', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [fixture('sample.png'), fixture('sample.wav')]);
    const alert = page.locator('#results > .alert.alert--error');
    await expect(alert).toBeVisible();
    await expect(alert).toContainText('"sample.png" is not an audio file');
    await expect(page.locator('.conv-row')).toHaveCount(1);
    await page.click('#convert');
    await expect(page.locator('.conv-row[data-status="done"]')).toHaveCount(1, { timeout: 30_000 });
  });

  test('a file with an audio name that cannot be decoded fails on its row only', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [
      { name: 'broken.flac', mimeType: 'audio/flac', buffer: Buffer.from('not really audio data at all') },
      { name: 'sample.wav', mimeType: 'audio/wav', buffer: WAV },
    ]);
    await page.click('#convert');
    await expect(page.locator('.conv-row[data-status="done"]')).toHaveCount(1, { timeout: 30_000 });
    const bad = page.locator('.conv-row[data-status="error"]');
    await expect(bad).toHaveCount(1);
    await expect(bad.locator('.alert--error')).toContainText('cannot decode FLAC');
  });

  test('keyboard: Enter converts, Delete removes the focused row, Clear resets', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [
      { name: 'one.wav', mimeType: 'audio/wav', buffer: WAV },
      { name: 'two.wav', mimeType: 'audio/wav', buffer: WAV },
    ]);
    await page.locator('.conv-row').first().focus();
    await page.keyboard.press('Delete');
    await expect(page.locator('.conv-row')).toHaveCount(1);
    await expect(page.locator('.conv-row .result__name')).toHaveText('two.wav');
    await page.locator('.conv-row').first().focus();
    await page.keyboard.press('Enter');
    await expect(page.locator('.conv-row[data-status="done"]')).toHaveCount(1, { timeout: 30_000 });
    await page.click('#clear');
    await expect(page.locator('.conv-row')).toHaveCount(0);
    await expect(page.locator('#empty-state')).toBeVisible();
  });

  test('mono option encodes a mono MP3', async ({ page }) => {
    await page.goto('./');
    await page.selectOption('#channels', 'mono');
    await convert(page);
    await expect(page.locator('.conv-format')).toContainText('mono · 44,100 Hz');
  });

  test('works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    const files = [
      { name: 'a-rather-long-file-name-from-a-field-recording-session-number-one.wav', mimeType: 'audio/wav', buffer: WAV },
      { name: 'sample.wav', mimeType: 'audio/wav', buffer: WAV },
    ];
    await convert(page, { files });
    await expect(page.locator('#download-zip')).toBeVisible();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    const box = await page.locator('.conv-row__download').first().boundingBox();
    expect(box.x + box.width).toBeLessThanOrEqual(391);
    const { bytes } = await downloadFirst(page);
    expect(isMp3(bytes)).toBeTruthy();
  });

  test('__demo shows a finished conversion', async ({ page }) => {
    await page.goto('./');
    await page.evaluate(() => window.__demo());
    await expect(page.locator('.conv-row[data-status="done"]')).toHaveCount(1);
    await expect(page.locator('.conv-row__download')).toHaveText('Download piano-arpeggio.mp3');
  });
});
